<script lang="ts" setup>
import type { MockupExample, WatermarkSetting } from '~/utils/types'
import { formatedDate, formatTimeMinutes, timeStyle } from '~/utils/datetime'

// 样机预览区：渲染背景与 selectedProto 中的所有设备（含锁屏时间/小组件/水印）
// 纯展示组件，状态由页面传入；点击与背景加载通过事件上抛
const props = defineProps<{
  selectedProto: MockupExample
  backgroundUrl: string
  paperUrl: string
  selectedGradient: string
  backgroundColor: string
  fontRadio: string
  desktopRadio: number
  componentRadio: number
  componentText: string
  defaultComponentText: string
  waterSetting: WatermarkSetting
}>()

const emit = defineEmits<{
  (e: 'background-load' | 'background-click'): void
  (e: 'proto-click', name: string): void
}>()

// 模板 ref：页面导出（useImageExport）与智能配色（useColorExtract）经 defineExpose 访问
const resultImage = ref<HTMLElement | null>(null)
const paperImage = ref<HTMLImageElement[]>([])
defineExpose({ resultImage, paperImage })

const { locale } = useI18n()

function onBackgroundImageLoad() {
  emit('background-load')
}

function onBackgroundClick() {
  emit('background-click')
}

function onProtoClick(name: string) {
  emit('proto-click', name)
}

function waterSettingStyle() {
  const result = {
    color: props.waterSetting.color,
    'font-size': `${props.waterSetting.fontSize}px`,
    transform: `translateX(${props.waterSetting.translateX}px) translateY(${props.waterSetting.translateY}px)`
  }

  return result
}
</script>

<template>
<div id="content" ref='resultImage' class="content" style="width: 1200px; height: 1600px;">
  <template v-if="selectedProto.background.type == 'imageText'">
    <img
id="bg-image" class="bg-image" :src="backgroundUrl"
      :style="selectedProto.background.backgroundImageStyle?.() ?? {}" @load="onBackgroundImageLoad" >
    <canvas
id="bg-canvas" class="bg-canvas"
      :style="{ display: selectedProto.background.needBlur ? 'block' : 'none' }" />
  </template>

  <template v-if="selectedProto.background.type == 'gradient'">
    <div class="background" :style="{ background: selectedGradient }"/>
  </template>

  <template v-if="selectedProto.background.type == 'solidColor'">
    <div class="background" :style="{ backgroundColor: backgroundColor }"/>
  </template>

  <div class="main-page" @click="onBackgroundClick">
    <div
v-for="(proto, index) in selectedProto.protoList" :key="index"
      class="proto" :style="proto.style" @click.stop="onProtoClick(proto.name)">
      <!-- 边框部分 -->
      <img
v-if="proto.type == 'iphoneType' && proto.frame" crossorigin="" class="frame"
        src="/image/frame-1.png" >
      <img
v-if="proto.type == 'iphoneType' && proto.smartIsLand" crossorigin="" class="smart-isLand"
        src="/image/hair.png" >
      <div
v-if="proto.type == 'macType' && proto.frame"
        style="width: 4096px;height: 2459px;position: absolute;z-index: 20;">
        <img class="frame" src="/image/mac-modal.png" >
      </div>

      <!-- 壁纸内容 -->
      <div
v-if="['lockScreen', 'desktopScreen', 'onlyMockUp'].includes(proto.screenType)" class="paper"
        :style="proto.paperStyleMethod?.(proto) ?? {}">
        <img ref="paperImage" class="image" :src="paperUrl" >

        <!-- 平板/电脑界面的组件 -->
        <div
          v-if="['ipadType', 'macType'].includes(proto.type) && ['lockScreen', 'desktopScreen'].includes(proto.screenType)"
          style="position: absolute;top: 0;left: 0;width: 100%;height: 100%;display: flex;flex-direction: column;
align-items: center;">

          <!-- 电脑没有顶部的信号格 -->
            <MockupIpadStatusBar v-if="proto.type == 'ipadType'" :proto="proto" />

          <template v-if="proto.screenType == 'desktopScreen'">
            <svg
style="position: absolute;top: 0px;left: 0px;" width="100%" height="100%"
              :viewBox="proto.vertical ? '0 0 834 1194' : '0 0 1194 834'" fill="none"
              xmlns="http://www.w3.org/2000/svg">
              <g clip-path="url(#clip0_3_3531)">
                <g
filter="url(#filter0_b_3_3531)"
                  :transform="proto.vertical ? 'translate(-180, 360)' : ''">
